const http = require('http');
const crypto = require('crypto');

// Configuration management service with layered config support
const DEFAULT_CONFIG = {
  server: { port: 8080, host: '0.0.0.0', timeout: 30000 },
  security: { rateLimit: 100, maxBodySize: 65536, adminEnabled: false },
  logging: { level: 'info', destination: 'stdout' }
};

let activeConfig = JSON.parse(JSON.stringify(DEFAULT_CONFIG));
let configVersion = 0;

// Dangerous property blocklist
const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

// Deep merge utility - safely merges user overrides into config
function deepMerge(target, source, depth = 0) {
  if (depth > 10) return target; // Prevent infinite recursion
  if (typeof source !== 'object' || source === null) return target;
  if (typeof target !== 'object' || target === null) return source;

  const keys = Object.keys(source);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    // Security: block prototype pollution vectors
    if (BLOCKED_KEYS.has(key)) continue;
    // Only merge own properties, skip inherited
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue;

    // Only allow merging into keys that exist in DEFAULT_CONFIG structure
    if (!Object.prototype.hasOwnProperty.call(target, key)) continue;

    if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
      if (typeof target[key] !== 'object' || target[key] === null) {
        target[key] = {};
      }
      deepMerge(target[key], source[key], depth + 1);
    } else {
      // Type-check: only allow same type as existing value
      if (typeof source[key] === typeof target[key]) {
        target[key] = source[key];
      }
    }
  }
  return target;
}

// Session store
const sessions = new Map();

function createSession(userId, role) {
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId, role, created: Date.now() });
  return token;
}

function getSession(token) {
  if (typeof token !== 'string' || token.length !== 64) return null;
  const session = sessions.get(token);
  if (!session) return null;
  if (Date.now() - session.created > 3600000) {
    sessions.delete(token);
    return null;
  }
  return session;
}

// Auth middleware
function authenticate(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  return getSession(authHeader.slice(7));
}

// Normalize a string to a fixed-length (64-byte) buffer so that
// crypto.timingSafeEqual never throws on mismatched lengths.
function fixedLengthBuffer(str) {
  const buf = Buffer.alloc(64, 0);
  Buffer.from(String(str), 'utf8').copy(buf, 0, 0, 64);
  return buf;
}

// Route: Apply config overlay (admin only, strictly enforced)
function handleConfigUpdate(req, body, session) {
  if (session.role !== 'admin') {
    return { status: 403, body: { error: 'Admin access required' } };
  }

  let overlay;
  try {
    overlay = JSON.parse(body);
  } catch (e) {
    return { status: 400, body: { error: 'Invalid JSON' } };
  }

  // Validate overlay is a plain object
  if (typeof overlay !== 'object' || overlay === null || Array.isArray(overlay)) {
    return { status: 400, body: { error: 'Config must be an object' } };
  }

  // Ensure it's a plain object (not from a weird prototype chain)
  if (Object.getPrototypeOf(overlay) !== Object.prototype) {
    return { status: 400, body: { error: 'Invalid object type' } };
  }

  // Apply the overlay using safe deep merge
  deepMerge(activeConfig, overlay);
  configVersion++;

  return { status: 200, body: { message: 'Config updated', version: configVersion } };
}

// Route: Login with timing-safe comparison
function handleLogin(body) {
  let creds;
  try {
    creds = JSON.parse(body);
  } catch (e) {
    return { status: 400, body: { error: 'Invalid JSON' } };
  }

  const username = String(creds.username || '');
  const password = String(creds.password || '');

  if (!username || !password) {
    return { status: 400, body: { error: 'Missing credentials' } };
  }

  // Demo: hardcoded users with timing-safe password comparison
  const users = {
    'admin': { password: 'supersecret', role: 'admin' },
    'user': { password: 'userpass', role: 'viewer' }
  };

  const user = users[username];
  if (!user) {
    // Constant-time: still do a comparison to prevent timing oracle
    crypto.timingSafeEqual(
      fixedLengthBuffer(password),
      fixedLengthBuffer('x'.repeat(64))
    );
    return { status: 401, body: { error: 'Invalid credentials' } };
  }

  const passwordMatch = crypto.timingSafeEqual(
    fixedLengthBuffer(password),
    fixedLengthBuffer(user.password)
  );

  if (!passwordMatch) {
    return { status: 401, body: { error: 'Invalid credentials' } };
  }

  const token = createSession(username, user.role);
  return { status: 200, body: { token, role: user.role } };
}

// Route: Get current config (admin only)
function handleConfigGet(session) {
  if (session.role !== 'admin') {
    return { status: 403, body: { error: 'Admin access required' } };
  }
  return { status: 200, body: activeConfig };
}

// Route: Execute maintenance task (admin only)
function handleMaintenance(session) {
  if (session.role !== 'admin') {
    return { status: 403, body: { error: 'Admin only' } };
  }
  // Cleanup expired sessions
  const now = Date.now();
  let cleaned = 0;
  for (const [token, sess] of sessions) {
    if (now - sess.created > 3600000) {
      sessions.delete(token);
      cleaned++;
    }
  }
  return { status: 200, body: { cleaned } };
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    const maxSize = 65536; // Fixed, not from mutable config
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > maxSize) {
        req.destroy();
        reject(new Error('Body too large'));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

// Dynamic route handler registry (looks scary but is safe - only admin can register,
// and the Function constructor is never actually called with user input)
const routeHandlers = new Map();
function registerInternalRoute(path, handlerCode) {
  // This is only called at startup with hardcoded values
  // The Function constructor usage here is intentional for internal plugin system
  // It is NOT reachable from any HTTP endpoint
  const handler = new Function('session', 'body', handlerCode);
  routeHandlers.set(path, handler);
}

// Register built-in internal route (not user-accessible)
registerInternalRoute('/internal/health', 'return { status: "ok" }');

const server = http.createServer(async (req, res) => {
  const respond = (status, body) => {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(body));
  };

  try {
    if (req.method === 'POST' && req.url === '/login') {
      const body = await readBody(req);
      const result = handleLogin(body);
      return respond(result.status, result.body);
    }

    if (req.method === 'POST' && req.url === '/config') {
      const session = authenticate(req);
      if (!session) return respond(401, { error: 'Unauthorized' });
      const body = await readBody(req);
      const result = handleConfigUpdate(req, body, session);
      return respond(result.status, result.body);
    }

    if (req.method === 'GET' && req.url === '/config') {
      const session = authenticate(req);
      if (!session) return respond(401, { error: 'Unauthorized' });
      const result = handleConfigGet(session);
      return respond(result.status, result.body);
    }

    if (req.method === 'POST' && req.url === '/maintenance') {
      const session = authenticate(req);
      if (!session) return respond(401, { error: 'Unauthorized' });
      const result = handleMaintenance(session);
      return respond(result.status, result.body);
    }

    respond(404, { error: 'Not found' });
  } catch (e) {
    respond(500, { error: 'Internal error' });
  }
});

server.listen(DEFAULT_CONFIG.server.port);
